begin;

-- Fiches de théorie et grilles d'entraînement passent du dépôt à la base
-- (ADR-013) : l'administration les modifie sans redéploiement. Comme pour le
-- reste du catalogue, les étudiants ne lisent que ce qui est publié et toute
-- écriture passe par une RPC security definer appelée avec service_role.

create table public.theory_fiches (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) between 3 and 120),
  title text not null check (char_length(title) between 3 and 200),
  summary text not null check (char_length(summary) between 10 and 500),
  content text not null check (char_length(content) between 1 and 100000),
  position integer not null default 0,
  is_published boolean not null default false,
  version integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Le JSON de la grille est validé par l'application (lib/grids/validate.ts)
-- à l'écriture comme à la lecture ; la base n'en borne que la forme et la taille.
create table public.practice_grids (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) between 2 and 120),
  title text not null check (char_length(title) between 2 and 200),
  themes text not null default '' check (char_length(themes) <= 300),
  content jsonb not null check (jsonb_typeof(content) = 'object' and pg_column_size(content) <= 200000),
  position integer not null default 0,
  is_published boolean not null default false,
  version integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.theory_fiches enable row level security;
alter table public.practice_grids enable row level security;
create policy "theory_fiches_read_published" on public.theory_fiches
  for select to authenticated using (is_published = true);
create policy "practice_grids_read_published" on public.practice_grids
  for select to authenticated using (is_published = true);
revoke all on public.theory_fiches, public.practice_grids from anon, authenticated;
grant select on public.theory_fiches, public.practice_grids to authenticated;

-- Création (p_id null) ou mise à jour. La version attendue évite qu'un
-- enregistrement écrase silencieusement celui d'un autre admin. Le slug est
-- fixé à la création : il porte les adresses publiques et les sauvegardes locales.
create function public.admin_save_theory_fiche(
  p_admin_user_id uuid,
  p_id uuid,
  p_expected_version integer,
  p_slug text,
  p_title text,
  p_summary text,
  p_content text,
  p_position integer,
  p_is_published boolean
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not exists (
    select 1 from public.profiles
    where id = p_admin_user_id and role = 'admin'
  ) then
    raise exception 'admin access required';
  end if;

  if char_length(trim(p_title)) not between 3 and 200
    or char_length(trim(p_summary)) not between 10 and 500
    or char_length(trim(p_content)) not between 1 and 100000
    or p_position not between 0 and 10000 then
    raise exception 'invalid theory payload';
  end if;

  if p_id is null then
    insert into public.theory_fiches (slug, title, summary, content, position, is_published)
    values (p_slug, trim(p_title), trim(p_summary), trim(p_content), p_position, p_is_published)
    returning id into v_id;
    return v_id;
  end if;

  update public.theory_fiches set
    title = trim(p_title),
    summary = trim(p_summary),
    content = trim(p_content),
    position = p_position,
    is_published = p_is_published,
    version = version + 1,
    updated_at = now()
  where id = p_id and version = p_expected_version
  returning id into v_id;

  if v_id is null then
    if exists (select 1 from public.theory_fiches where id = p_id) then
      raise exception 'version conflict';
    end if;
    raise exception 'theory fiche not found';
  end if;
  return v_id;
end;
$$;

revoke all on function public.admin_save_theory_fiche(uuid, uuid, integer, text, text, text, text, integer, boolean)
  from public, anon, authenticated;
grant execute on function public.admin_save_theory_fiche(uuid, uuid, integer, text, text, text, text, integer, boolean)
  to service_role;

create function public.admin_save_practice_grid(
  p_admin_user_id uuid,
  p_id uuid,
  p_expected_version integer,
  p_slug text,
  p_title text,
  p_themes text,
  p_content jsonb,
  p_position integer,
  p_is_published boolean
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not exists (
    select 1 from public.profiles
    where id = p_admin_user_id and role = 'admin'
  ) then
    raise exception 'admin access required';
  end if;

  if char_length(trim(p_title)) not between 2 and 200
    or char_length(trim(coalesce(p_themes, ''))) > 300
    or p_content is null or jsonb_typeof(p_content) <> 'object'
    or p_position not between 0 and 10000 then
    raise exception 'invalid grid payload';
  end if;

  if p_id is null then
    insert into public.practice_grids (slug, title, themes, content, position, is_published)
    values (p_slug, trim(p_title), trim(coalesce(p_themes, '')), p_content, p_position, p_is_published)
    returning id into v_id;
    return v_id;
  end if;

  update public.practice_grids set
    title = trim(p_title),
    themes = trim(coalesce(p_themes, '')),
    content = p_content,
    position = p_position,
    is_published = p_is_published,
    version = version + 1,
    updated_at = now()
  where id = p_id and version = p_expected_version
  returning id into v_id;

  if v_id is null then
    if exists (select 1 from public.practice_grids where id = p_id) then
      raise exception 'version conflict';
    end if;
    raise exception 'practice grid not found';
  end if;
  return v_id;
end;
$$;

revoke all on function public.admin_save_practice_grid(uuid, uuid, integer, text, text, text, jsonb, integer, boolean)
  from public, anon, authenticated;
grant execute on function public.admin_save_practice_grid(uuid, uuid, integer, text, text, text, jsonb, integer, boolean)
  to service_role;

-- Contenu initial : la fiche socle et les huit grilles de l'ECOS de 3e année
-- (UNIL), jusqu'ici dans le dépôt. La base devient la référence.
insert into public.theory_fiches (slug, title, summary, content, position, is_published) values
  ($seed$anamnese-classique$seed$, $seed$Anamnèse classique$seed$, $seed$La trame commune à toutes les consultations : de la plainte aux antécédents, jusqu’à la conclusion.$seed$, $seed$> [!warning] Statut éditorial
> **À réviser.** Fiche rédigée à partir de notes de cours personnelles. Elle doit être relue et signée nominativement avant d'être considérée comme validée.

## En bref

L'anamnèse suit toujours la même trame, quel que soit le motif : **ouvrir**, **caractériser la plainte**, **balayer les systèmes**, **reprendre les antécédents et le contexte**, puis **conclure**. Cette trame est la colonne vertébrale de chaque station ; l'anamnèse spécifique à un système (cardio-pulmonaire, digestive, neurologique…) vient s'y greffer après la plainte.

- **Chaque « oui » se caractérise** : un symptôme évoqué mais non exploré ne rapporte rien.
- **Une à deux questions par système**, même hors sujet : c'est souvent là que se cache la piste.
- **Les médicaments et les allergies** sont les oublis les plus fréquents.
- **La conclusion** (résumé, teach-back, questions) est la partie qui rapporte le plus de points.

## Ouvrir l'entretien

- Se présenter (nom, fonction) et vérifier l'identité du patient : nom, âge.
- Poser le cadre : but et déroulé de la consultation, durée.
- Créer un climat de confiance ; s'assurer du confort du patient.
- Commencer par une **question ouverte**, puis laisser parler sans interrompre.

> [!example] Phrases d'ouverture
> - « Qu'est-ce qui vous amène aujourd'hui ? »
> - « Racontez-moi depuis le début. »

## Motif de consultation

- Le motif en une phrase, **avec les mots du patient**.
- S'il y a plusieurs plaintes, les lister puis les hiérarchiser avec lui : « Qu'est-ce qui vous gêne le plus ? »

## Anamnèse actuelle

Caractériser la plainte principale, toujours dans le même ordre.

**Caractériser un symptôme :**
- **Localisation** et **irradiation**.
- **Qualité** : serrement, brûlure, pulsatile, coup de poignard, douleur sourde…
- **Intensité** : échelle de 0 à 10, retentissement sur le quotidien.
- **Chronologie** : début (brutal ou progressif), durée, fréquence, évolution depuis le début.
- **Circonstances de survenue** : au repos, à l'effort, la nuit, après un repas…
- **Facteurs aggravants et soulageants** : position, effort, alimentation, médicaments déjà essayés.
- **Premier épisode ?** Si non, comment se sont passés les précédents.
- **Symptômes associés**.

**Le vécu du patient :**
- Ce qu'il pense avoir, ce qui l'inquiète, ce qu'il attend de la consultation.
- Nommer et valider les émotions exprimées.

> [!tip] Après la plainte
> C'est ici que s'insère l'anamnèse spécifique au système concerné : on creuse les symptômes propres à l'appareil suspecté avant de passer au balayage général.

## Anamnèse générale

À poser systématiquement, notamment pour les **symptômes B** :

- Fièvre, frissons.
- Sudations nocturnes.
- Perte de poids involontaire (combien, en combien de temps).
- Fatigue, perte d'appétit.

## Revue des systèmes

**Une à deux questions par système**, rapidement, sans tout détailler. Chaque réponse positive se caractérise comme la plainte principale.

| Système | Questions types |
|---|---|
| Neurologique | Maux de tête ? Vertiges ? Troubles de la vision ? |
| Cardiovasculaire | Douleur thoracique ? Palpitations ? Œdèmes des jambes ? |
| Pulmonaire | Essoufflement ? Toux ? Expectorations ? |
| Digestif | Douleurs abdominales ? Nausées, vomissements ? Changement des selles ? |
| Urinaire | Brûlures en urinant ? Envies fréquentes ? Sang dans les urines ? |
| Gynécologique | Date des dernières règles ? Cycles réguliers ? Contraception ? Grossesse possible ? |
| Locomoteur et peau | Douleurs articulaires ? Éruption, démangeaisons ? |
| Ganglions | Ganglions gonflés ? |
| Psychique | Stress ? Moral ? Sommeil ? |

Terminer par une question ouverte : « Avez-vous remarqué d'autres symptômes ? »

## Antécédents personnels

- **Maladies connues** : HTA, diabète, dyslipidémie, maladie thromboembolique, infections à répétition…
- **Opérations** et **hospitalisations**, surtout récentes.
- **Gynéco-obstétrique** : grossesses, accouchements.
- **Vaccinations** : à jour ?

## Traitements et allergies

- **Tous les médicaments** : nom, dose, depuis quand, observance. Penser à demander spécifiquement :
  - la contraception orale et les œstrogènes ;
  - les anti-inflammatoires (AINS) ;
  - les anticoagulants et antiagrégants ;
  - l'automédication, les traitements topiques, les produits naturels.
- **Allergies** : médicaments, aliments, autres ; quel type de réaction.

> [!warning] Oubli fréquent
> Les médicaments sont souvent oubliés, alors qu'ils peuvent expliquer le tableau (effet indésirable, toxidermie, interaction).

## Antécédents familiaux

- Maladies dans la famille proche (parents, fratrie, enfants), **en précisant l'âge de survenue**.
- Cardiovasculaire précoce, cancers, maladies héréditaires, diabète, troubles psychiques, addictions.

## Habitudes de vie

- **Tabac** : actif, sevré ou jamais ; quantité en unités paquets-année.
- **Alcool** : quantité et fréquence.
- **Drogues** : lesquelles, voie d'administration (intraveineuse ?).
- **Alimentation**, **activité physique**, **sommeil**.

## Contexte psychosocial et expositions

- **Travail** : profession, conditions, expositions, stress.
- **Logement** et **entourage** : seul, en couple, famille, aidants.
- **Loisirs**, **voyages** récents, **animaux**, promenades en forêt (tiques).
- **Contage** : personnes malades dans l'entourage.

## Anamnèse sexuelle

À aborder lorsque c'est pertinent, après avoir annoncé la question et rappelé la confidentialité.

> [!example] Introduire le sujet
> « Je vais vous poser quelques questions plus personnelles, que je pose à tous mes patients. Avez-vous un, une ou des partenaires sexuels ? »

- **Partenaires** : genre, nombre, date du dernier rapport.
- **Pratiques** : orale, vaginale, anale.
- **Exclusivité** de la relation.
- **Protection et contraception** : laquelle, pour quels rapports.

## Conclure l'entretien

- **Résumer** ce qui a été dit et vérifier : « Est-ce que j'ai bien résumé ? Ai-je oublié quelque chose ? »
- **Annoncer la suite** : examen clinique, examens complémentaires, plan.
- **Teach-back** : demander au patient de reformuler ce qu'il a retenu.
- **Questions** : « Avez-vous encore une question ? »

## Techniques de communication

- **Questions ouvertes** d'abord, fermées ensuite pour préciser.
- **Silences** : ils laissent au patient la place d'en dire plus.
- **Rebondir** sur un mot du patient : « Qu'entendez-vous par là ? »
- **Récapituler** régulièrement : le patient ajoute souvent ce qu'il avait omis.
- **Empathie** : « Je comprends… ça ne doit pas être facile. »
- **Vocabulaire simple**, sans jargon.

## Provenance

- Synthèse de notes de cours personnelles (stations ECOS : cardio-pulmonaire, abdominale, neurologique, dermatologique, fièvre, psychosocial).
- Statut : **À réviser — non signée**.$seed$, 1, true);

